public class Main {
    static int calc(String[] names, int[] scores, int i) {
        try {
            return names[i].length() / scores[i];
        } catch (ArithmeticException e) {
            return -1;
        } finally {
            System.out.print("f" + i + " ");
        }
    }
    public static void main(String[] args) {
        String[] names = new String[3];
        int[] scores = new int[3];
        double[] avg = new double[2];
        names[0] = "kim";
        scores[0] = 3;
        names[2] = "lee";
        int sum = 0;
        try {
            for (int i = 0; i < 3; i++) {
                sum += calc(names, scores, i);
            }
        } catch (NullPointerException e) {
            System.out.print("NPE ");
        }
        System.out.println(sum);
        System.out.print(avg[1] + " " + names[1]);
    }
}

interface Greeter {
    default String greet() { return "G"; }
    String name();
}
abstract class Base {
    public String greet() { return "B"; }
    abstract String tag();
    String run() { return "[" + tag() + greet() + "]"; }
}
class Impl extends Base implements Greeter {
    public String name() { return "I"; }
    String tag() { return name() + "t"; }
}
class Impl2 extends Impl {
    public String greet() { return "X" + super.greet(); }
    public String name() { return "J"; }
}
class Solo implements Greeter {
    public String name() { return "S"; }
}
public class Main {
    public static void main(String[] args) {
        Greeter g1 = new Impl();
        Greeter g2 = new Solo();
        System.out.println(g1.greet() + g2.greet() + g2.name());
        Base b = new Impl2();
        System.out.print(b.run());
    }
}

