    int total;
    int cnt;
}

public class Main {
    static void add(Acc a, int n) {
        a.total += n;
        a.cnt++;
        n = 0;
    }

    static void reset(Acc a) {
        a = new Acc();
        a.total = 1;
    }

    public static void main(String[] args) {
        Acc x = new Acc();
        int n = 7;
        add(x, n);
        add(x, n * 2);
        reset(x);
        x.total *= x.cnt;
        System.out.printf("%d %d", x.total, n);
    }
}

