    int y, x, i, j;

    for (y = 0; y < 3; y++) {
        for (x = 0; x < 4; x++) {
            if (field[y][x] == 0) continue;
            for (i = y - 1; i <= y + 1; i++) {
                for (j = x - 1; j <= x + 1; j++) {
                    if (inBound(i, j) == 1 && !(i == y && j == x))
                        cnt[i][j]++;
