typedef struct { int id; double bal; } Wallet;

double rate_pow(double r, int n) {
    double x = 1.0;
    while (n-- > 0)
        x = x * r;
    return x;
}

void init(Wallet *w, int id, double b) {
    w->id = id;
    w->bal = b;
}

void pay(Wallet *w, double *amt) {
    if (*amt > 0 && *amt <= w->bal)
        w->bal = w->bal - *amt;
    else
        w->bal = w->bal + *amt;
}

void grow(Wallet *w) {
    w->bal = w->bal * rate_pow(1.2, 2);
}

