    n->value = value;
    n->next = head;
    return n;
}

Data *toTail(Data *head, int value) {
    Data *prev = NULL, *curr = head, *last = head;
    while (curr->value != value) {
        prev = curr;
        curr = curr->next;
    }
    while (last->next != NULL) last = last->next;
    prev->next = curr->next;
    last->next = curr;
    curr->next = NULL;
    return head;
}

