abstract class Shape {
    String name;
    Shape(String name) { this.name = name; }
    abstract int area();
    void show() { System.out.println(name + ":" + area()); }
}

class Rect extends Shape {
    int w, h;
    Rect(int w, int h) { super("R"); this.w = w; this.h = h; }
    int area() { return w * h; }
}

class Tri extends Shape {
    int b, h;
    Tri(int b, int h) { super("T"); this.b = b; this.h = h; }
    int area() { return b * h / 2; }
    void show() { System.out.print("*"); super.show(); }
}

public class Main {
    public static void main(String[] args) {
        Shape[] s = { new Rect(3, 4), new Tri(5, 3) };
        int sum = 0;
        for (Shape x : s) { x.show(); sum += x.area(); }
        System.out.println(sum);
    }
}

